const body = $input.first().json.body || $input.first().json;

const candidature_id  = body.candidature_id  || '';
const cv_base64       = body.cv_base64       || '';
const cv_mimetype     = body.cv_mimetype     || 'application/pdf';
const callback_url    = body.callback_url    || '';
const callback_secret = body.callback_secret || '';

if (!candidature_id) throw new Error('candidature_id manquant dans le payload');
if (!cv_base64)      throw new Error('cv_base64 manquant dans le payload');
if (!callback_url)   throw new Error('callback_url manquant dans le payload');

const prompt = `Tu es un assistant RH. Extrais les informations suivantes du CV fourni.

Réponds UNIQUEMENT en JSON valide, sans markdown, sans backticks, sans texte avant ou après :
{
  "candidat_nom": "Prénom NOM complet",
  "candidat_email": "email@exemple.com",
  "candidat_telephone": "+XXX XX XX XX XX"
}

Règles :
- candidat_nom : prénom + nom complet correctement mis en forme (ex: "Jean DUPONT"). Obligatoire.
- candidat_email : adresse email valide si présente, sinon null
- candidat_telephone : numéro de téléphone si présent (format international si possible), sinon null
- Si plusieurs emails ou téléphones, prendre le premier trouvé
- Ne jamais inventer d'information — mettre null si absent`;

return [{ json: {
  candidature_id,
  callback_url,
  callback_secret,
  requestBody: {
    model: 'claude-sonnet-4-6',
    max_tokens: 512,
    messages: [
      {
        role: 'user',
        content: [
          {
            type: 'document',
            source: {
              type: 'base64',
              media_type: cv_mimetype,
              data: cv_base64
            }
          },
          {
            type: 'text',
            text: prompt
          }
        ]
      }
    ]
  }
}}];

const claudeResponse = $input.first().json;
const prevData = $('03 — Préparer prompt extraction').first().json;

const raw = claudeResponse?.content?.[0]?.text || '';
if (!raw) throw new Error('Réponse Claude vide — content[0].text absent');

// Retirer les balises markdown si présentes
const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
const jsonStr = fenceMatch ? fenceMatch[1].trim() : raw.trim();

let parsed;
try {
  parsed = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('Impossible de parser la réponse Claude : ' + e.message + ' — Extrait : ' + jsonStr.slice(0, 200));
}

const nom   = (parsed.candidat_nom   || '').trim() || 'Candidat sans nom';
const email = (parsed.candidat_email || null);
const tel   = (parsed.candidat_telephone || null);

console.log(`✅ Extraction WF5 pour ${prevData.candidature_id} : nom=${nom}, email=${email || 'null'}, tel=${tel || 'null'}`);

return [{ json: {
  candidature_id:    prevData.candidature_id,
  callback_url:      prevData.callback_url,
  callback_secret:   prevData.callback_secret,
  candidat_nom:      nom,
  candidat_email:    email,
  candidat_telephone: tel
}}];
